attributes.cssVariables:
:root {
  /* Paper. Riso prints on white stock and the stock stays white. */
  --background: #ffffff;
  --foreground: #000000;
  --card: #ffffff;
  --card-foreground: #000000;
  --popover: #ffffff;
  --popover-foreground: #000000;

  /* The inks. Every one takes BLACK type, not white — measured, not assumed:
     fluorescent pink on white is only 3.50:1 and could never carry text, but
     black on that same pink is 6.00:1. That is why riso art is black-on-ink. */
  --primary: #ff2e88;
  --primary-foreground: #000000;
  --secondary: #ffe800;
  --secondary-foreground: #000000;
  --accent: #00e5ff;
  --accent-foreground: #000000;
  --destructive: #ff4438;
  --destructive-foreground: #000000;

  --muted: #f4f4f4;
  --muted-foreground: #3d3d3d;

  /* Brutalist: the border is structure, not decoration. Full-strength black,
     and thick enough to read as a drawn line. */
  --border: #000000;
  --input: #000000;
  --ring: #ff2e88;

  /* No rounding. A brutalist surface has corners. */
  --radius: 0rem;

  --font-sans: 'Space Grotesk', system-ui, sans-serif;
  --font-heading: 'Archivo Black', 'Space Grotesk', system-ui, sans-serif;
  --font-serif: 'Space Grotesk', system-ui, sans-serif;
  --font-mono: 'Space Mono', ui-monospace, monospace;

  /* Hard shadows with zero blur — an offset block of ink, the way a second
     pass of the drum lands slightly off register. A blurred shadow would be
     the one un-brutalist thing on the page. */
  --shadow-xs: 2px 2px 0 #000000;
  --shadow-sm: 3px 3px 0 #000000;
  --shadow-md: 5px 5px 0 #000000;
  --shadow-lg: 8px 8px 0 #000000;
}

h1,
h2,
h3 {
  font-family: var(--font-heading);
  letter-spacing: -0.03em;
  text-transform: uppercase;
}

h1 {
  line-height: 0.92;
}
